public void init()
{
    FormRun formRunCaller = this.formRun().args().caller();

    next init();

    //FormDataObject dataObject = any2Object(this) as FormDataObject;
    //FormDataSource fds = dataObject.dataSource().formRun().dataSource(formDataSourceStr(GUPPriceRebatePriceAttributeGroupEdit, TAMRebateTable));
    FormDataSource fds = this as FormDataSource;

    if(formRunCaller.args().menuItemName() == menuitemdisplaystr(TAMRebateDealListPageVendRebate))
    {
        fds.object(fieldNum(TAMRebateTable, RebateAgreementType)).enabled(false);
    }
    else
    {
        fds.object(fieldNum(TAMRebateTable, RebateAgreementType)).enabled(true);
    }

}
